import { CoreMetrics, type CoreMetricsData } from "@/components/CoreMetrics";
import { ShippingStatus } from "@/components/ShippingStatus";
import coreMetrics from "@/generated/core-metrics.json";
import { loadShell } from "@/lib/server";

export const metadata = { title: "Quality · Foresight" };

/** Always on (TASKS: Quality): reports honestly whatever is shipped and what is still planned,
 *  led by the core metrics of the accepted evaluation run (generated by tools/render_results.py). */
export default async function QualityPage() {
  const { features } = await loadShell();
  return (
    <main className="page section-page" id="main">
      <h1>Quality checks</h1>
      <p className="lede">
        Each feature is switched on only when its evaluation passes. Full results are published in the repository’s
        README and evals/results.
      </p>
      <CoreMetrics data={coreMetrics as CoreMetricsData} />
      <ShippingStatus features={features} />
    </main>
  );
}
